(4456622, 641972, 73250, '<td valign="top">I love this...the fisheye really works well here...it gives that bigger than life feel and makes the viewer feel very small. Well done.</td>', 'I love this...the fisheye really works well here...it gives that bigger than life feel and makes the viewer feel very small. Well done.', '2008-02-04 09:02:55.000000', NULL, 1),
(4456623, 642085, 73250, '<td valign="top">Of all the between the legs shots...this is the best. The white starkness gives it a real sanitized feel and I like the focus on the gloves.</td>', 'Of all the between the legs shots...this is the best. The white starkness gives it a real sanitized feel and I like the focus on the gloves.', '2008-02-04 09:02:59.000000', NULL, 1),
(4456624, 641782, 73250, '<td valign="top">Great image...the tone suits it and it really speaks childhood to me! The motion really adds to it.</td>', 'Great image...the tone suits it and it really speaks childhood to me! The motion really adds to it.', '2008-02-04 09:03:02.000000', NULL, 1),
