(4459678, 642095, 84438, '<td valign="top">Heh.  Fantastic as always.</td>', 'Heh.  Fantastic as always.', '2008-02-05 10:07:23.000000', NULL, 1),
(4459681, 642074, 84438, '<td valign="top">Sorry, but this image just doesn''t speak to me.  A bit too noisy for my taste as well.</td>', 'Sorry, but this image just doesn''t speak to me.  A bit too noisy for my taste as well.', '2008-02-05 10:08:40.000000', NULL, 1),
(4459684, 640377, 84438, '<td valign="top">Great idea!  The lighting looks a bit too harsh though, and the colours are quite washed out.  I really like the composition and contrast though.</td>', 'Great idea!  The lighting looks a bit too harsh though, and the colours are quite washed out.  I really like the composition and contrast though.', '2008-02-05 10:09:44.000000', NULL, 1),
(4459688, 642085, 84438, '<td valign="top">Ha!  Pretty graphic!  Nicely done.  Unfortunately not an original idea in this challenge though, but I think that yours might be the best of the bunch.</td>', 'Ha!  Pretty graphic!  Nicely done.  Unfortunately not an original idea in this challenge though, but I think that yours might be the best of the bunch.', '2008-02-05 10:10:34.000000', NULL, 1),
(4459689, 640766, 84438, '<td valign="top">Love the processing!  How unique!  Big fan of this photo.</td>', 'Love the processing!  How unique!  Big fan of this photo.', '2008-02-05 10:11:09.000000', NULL, 1),
(4459696, 642009, 84438, '<td valign="top">The composition is good, but I do wish it was zoomed out a bit more.  I like it though.. Nice and simple.</td>', 'The composition is good, but I do wish it was zoomed out a bit more.  I like it though.. Nice and simple.', '2008-02-05 10:11:59.000000', NULL, 1),
(4459710, 641695, 84438, '<td valign="top">Haha.  Funny idea.  I wish the clock were more in focus though!</td>', 'Haha.  Funny idea.  I wish the clock were more in focus though!', '2008-02-05 10:14:33.000000', NULL, 1),
(4459711, 641630, 84438, '<td valign="top">Hmmm..  Neat idea, but the processing just doesn''t do it for me.</td>', 'Hmmm..  Neat idea, but the processing just doesn''t do it for me.', '2008-02-05 10:15:00.000000', NULL, 1),
(4459714, 642089, 84438, '<td valign="top">This would really be set off with a darker background I think.</td>', 'This would really be set off with a darker background I think.', '2008-02-05 10:15:21.000000', NULL, 1),
(4459715, 641162, 84438, '<td valign="top">Love the colours and the composition!</td>', 'Love the colours and the composition!', '2008-02-05 10:15:38.000000', NULL, 1),
(4459719, 641649, 84438, '<td valign="top">Yikes.  That''s one scary looking thing.  Fantastic macro!</td>', 'Yikes.  That''s one scary looking thing.  Fantastic macro!', '2008-02-05 10:16:05.000000', NULL, 1),
(4459723, 639676, 84438, '<td valign="top">Yeehaw!  Love the colours and composition!  Nice work!!</td>', 'Yeehaw!  Love the colours and composition!  Nice work!!', '2008-02-05 10:16:48.000000', NULL, 1),
(4459725, 640277, 84438, '<td valign="top">Nice photo, but I find it to be a bit too busy for my liking!</td>', 'Nice photo, but I find it to be a bit too busy for my liking!', '2008-02-05 10:17:19.000000', NULL, 1),
(4459730, 641492, 84438, '<td valign="top">Very unique!  I see where you''re going with this.  Points for your OOTB thinking!</td>', 'Very unique!  I see where you''re going with this.  Points for your OOTB thinking!', '2008-02-05 10:18:00.000000', NULL, 1),
(4459735, 641919, 84438, '<td valign="top">Love the composition in this.  You got the lighting just right without blowing anything out..  Not an easy feat!</td>', 'Love the composition in this.  You got the lighting just right without blowing anything out..  Not an easy feat!', '2008-02-05 10:18:55.000000', NULL, 1),
(4459740, 641971, 84438, '<td valign="top">You know, it''s a very nice photo technically, but I''m just so tired of ''splash'' photos.  It seems to be a bit of a shoehorn as well.  I apologize if that sounds harsh.</td>', 'You know, it''s a very nice photo technically, but I''m just so tired of ''splash'' photos.  It seems to be a bit of a shoehorn as well.  I apologize if that sounds harsh.', '2008-02-05 10:20:37.000000', NULL, 1),
(4459743, 641867, 84438, '<td valign="top">Heh.  I know who took this one!  <br/>Your lighting is fantastic.  A great photo as usual!!</td>', 'Heh.  I know who took this one!  Your lighting is fantastic.  A great photo as usual!!', '2008-02-05 10:21:34.000000', NULL, 1),
(4459746, 642066, 84438, '<td valign="top">That''s unique!  Pretty noise though!</td>', 'That''s unique!  Pretty noise though!', '2008-02-05 10:22:06.000000', NULL, 1),
(4459821, 641900, 84438, '<td valign="top">Wow that does not look appetizing at all. :)<br/>Very nice DOF and composition.</td>', 'Wow that does not look appetizing at all. :)Very nice DOF and composition.', '2008-02-05 10:49:28.000000', NULL, 1),
(4459823, 641198, 84438, '<td valign="top">Nice perspective and unique photo.  I like it a lot.</td>', 'Nice perspective and unique photo.  I like it a lot.', '2008-02-05 10:50:11.000000', NULL, 1),
(4459830, 641619, 84438, '<td valign="top">Your lighting and composition is just fantastic.  A simple but perfect photo.</td>', 'Your lighting and composition is just fantastic.  A simple but perfect photo.', '2008-02-05 10:52:00.000000', NULL, 1),
(4459833, 641958, 84438, '<td valign="top">Now that''s just gross. :)  Unfortunately, others have done this same idea in this challenge much better.. Sorry.</td>', 'Now that''s just gross. :)  Unfortunately, others have done this same idea in this challenge much better.. Sorry.', '2008-02-05 10:53:02.000000', NULL, 1),
(4459837, 640223, 84438, '<td valign="top">Hmmm...  A nice photo, but I wish there were more contrast to really make the subject stand out.  Maybe check your histogram for where your highlights sit?</td>', 'Hmmm...  A nice photo, but I wish there were more contrast to really make the subject stand out.  Maybe check your histogram for where your highlights sit?', '2008-02-05 10:54:12.000000', NULL, 1),
(4459839, 641804, 84438, '<td valign="top">I see what you are doing with this image (The perspective from the crib), but I don''t find the composition to make for a very pleasing photograph.  Sorry.</td>', 'I see what you are doing with this image (The perspective from the crib), but I don''t find the composition to make for a very pleasing photograph.  Sorry.', '2008-02-05 10:55:10.000000', NULL, 1),
(4459843, 642101, 84438, '<td valign="top">That''s nasty looking!  Very dark but I like your DOF and composition.</td>', 'That''s nasty looking!  Very dark but I like your DOF and composition.', '2008-02-05 10:55:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4459845, 640267, 84438, '<td valign="top">So nice.  Would be nicer if the child was in the sunlight as well, but still a great photo.</td>', 'So nice.  Would be nicer if the child was in the sunlight as well, but still a great photo.', '2008-02-05 10:56:20.000000', NULL, 1),
(4459851, 641929, 84438, '<td valign="top">First of all, let me start by saying that this is a beautiful photograph.<br/>But you are in the unfortunate position of having Aurora Borealis as your subject, a favourite of [user]Laurus[/user], who is most definately one of (if not) the best photographers on the site..<br/> <br/>So fair or not, your photograph is almost guaranteed to be judged against Laurus''.  Good luck with that. ;)</td>', 'First of all, let me start by saying that this is a beautiful photograph.But you are in the unfortunate position of having Aurora Borealis as your subject, a favourite of [user]Laurus[/user], who is most definately one of (if not) the best photographers on the site.. So fair or not, your photograph is almost guaranteed to be judged against Laurus''.  Good luck with that. ;)', '2008-02-05 11:00:31.000000', NULL, 1),
(4459853, 641933, 84438, '<td valign="top">This is a great photograph.  The colours are beautiful!<br/>This challenge is very open to interpretation, so I''m not going to claim that this is a ''shoehorn'' (Though others inevitably will).  However, this just doesn''t speak to me with respect to the challenge.  My opinion.</td>', 'This is a great photograph.  The colours are beautiful!This challenge is very open to interpretation, so I''m not going to claim that this is a ''shoehorn'' (Though others inevitably will).  However, this just doesn''t speak to me with respect to the challenge.  My opinion.', '2008-02-05 11:02:31.000000', NULL, 1),
(4459858, 640780, 84438, '<td valign="top">Ha!  Extra points for a laugh and your OOTB thinking.</td>', 'Ha!  Extra points for a laugh and your OOTB thinking.', '2008-02-05 11:03:09.000000', NULL, 1),
(4459866, 641895, 84438, '<td valign="top">Ha!  This is great!  Really gives the feeling of an old time photo.</td>', 'Ha!  This is great!  Really gives the feeling of an old time photo.', '2008-02-05 11:05:57.000000', NULL, 1),
(4459878, 641649, 51538, '<td valign="top">Yes.  I can understand that.  We used to have dinner-plate-sized hairy black tarantulas crawling over my bedroom ceiling in our outback home in Western Australia when I was tiny.  I remember them well.</td>', 'Yes.  I can understand that.  We used to have dinner-plate-sized hairy black tarantulas crawling over my bedroom ceiling in our outback home in Western Australia when I was tiny.  I remember them well.', '2008-02-05 11:10:34.000000', NULL, 1),
(4459880, 641630, 51538, '<td valign="top">Hard to depict such a thing - but I think you did well.  I used to have recurring nightmares of giant wheels rolling and rolling in abstract space...  Memorable to this day but impossible to describe really.  Not sure how many voters will understand though ;-)</td>', 'Hard to depict such a thing - but I think you did well.  I used to have recurring nightmares of giant wheels rolling and rolling in abstract space...  Memorable to this day but impossible to describe really.  Not sure how many voters will understand though ;-)', '2008-02-05 11:11:11.000000', NULL, 1),
(4460156, 641649, 69368, '<td valign="top">buah, is this a disgusting spider! - But this macro is great!</td>', 'buah, is this a disgusting spider! - But this macro is great!', '2008-02-05 12:48:30.000000', NULL, 1),
(4460166, 642126, 88473, '<td valign="top">This is great!!!!</td>', 'This is great!!!!', '2008-02-05 12:51:09.000000', NULL, 1),
(4460181, 642121, 49109, '<td valign="top">it''s clearly visible  you extended the canvas size by more than 200%. at least you could have chosen the same tone as the original background</td>', 'it''s clearly visible  you extended the canvas size by more than 200%. at least you could have chosen the same tone as the original background', '2008-02-05 12:55:53.000000', NULL, 1),
(4460193, 640766, 49109, '<td valign="top">interesting approach and nice artsy post-processing. Might have been better, if you had taken a childs POV</td>', 'interesting approach and nice artsy post-processing. Might have been better, if you had taken a childs POV', '2008-02-05 12:58:32.000000', NULL, 1),
(4460301, 642009, 6667, '<td valign="top">YESSSS!!!!</td>', 'YESSSS!!!!', '2008-02-05 13:39:08.000000', NULL, 1),
(4460541, 641619, 55892, '<td valign="top">Sweet face.  The reflection in  the eyes could benefit with some touching up.</td>', 'Sweet face.  The reflection in  the eyes could benefit with some touching up.', '2008-02-05 15:01:22.000000', NULL, 1),
(4460684, 640618, 55892, '<td valign="top">That is one scary bee!  I have a similar "earlist memory" of  a bee too.   The black background makes it hard to see the bee. (Of course that''s  why we get stung!)</td>', 'That is one scary bee!  I have a similar "earlist memory" of  a bee too.   The black background makes it hard to see the bee. (Of course that''s  why we get stung!)', '2008-02-05 16:08:02.000000', NULL, 1),
(4460686, 642101, 55892, '<td valign="top">Good concept.  Could be better with more light.</td>', 'Good concept.  Could be better with more light.', '2008-02-05 16:08:26.000000', NULL, 1),
(4460691, 641804, 55892, '<td valign="top">Beautiful photo.  That is truly how babies see, looking up.  I enjoyed the effects of the shadows.</td>', 'Beautiful photo.  That is truly how babies see, looking up.  I enjoyed the effects of the shadows.', '2008-02-05 16:11:44.000000', NULL, 1),
(4460693, 641423, 55892, '<td valign="top">Did you intend to have mom''s face out of focus?  By the time babys are old enouth for solid food their vision is good enough to see better than that,(I think).</td>', 'Did you intend to have mom''s face out of focus?  By the time babys are old enouth for solid food their vision is good enough to see better than that,(I think).', '2008-02-05 16:12:46.000000', NULL, 1),
(4460732, 641782, 89522, '<td valign="top">This is a view i now remember after looking at this picture. The woman even moves, the colors match the memory. Well done, Great job.</td>', 'This is a view i now remember after looking at this picture. The woman even moves, the colors match the memory. Well done, Great job.', '2008-02-05 16:23:29.000000', NULL, 1),
(4460736, 642095, 89522, '<td valign="top">This is how it was, but this one realy made me laugh. How in the world did you squeeze that woman in this tub? Very nice composition! I can''t vote, but I should have marked it a 9.</td>', 'This is how it was, but this one realy made me laugh. How in the world did you squeeze that woman in this tub? Very nice composition! I can''t vote, but I should have marked it a 9.', '2008-02-05 16:24:28.000000', NULL, 1),
(4460760, 641919, 89522, '<td valign="top">You did catch hapiness and the sensation of floating down. In the Netherlands we did not have such snow for ages, for me this is a early memory. Nice composition/angle, realy feels like he comes from the upper left.</td>', 'You did catch hapiness and the sensation of floating down. In the Netherlands we did not have such snow for ages, for me this is a early memory. Nice composition/angle, realy feels like he comes from the upper left.', '2008-02-05 16:28:09.000000', NULL, 1),
(4460845, 641193, 62787, '<td valign="top">Eek. Extremely striking image! Beautifully composed, in a sort of rather freaky way... :)<br/>Gah, can''t stop staring...</td>', 'Eek. Extremely striking image! Beautifully composed, in a sort of rather freaky way... :)Gah, can''t stop staring...', '2008-02-05 16:48:13.000000', NULL, 1),
(4460863, 642114, 62787, '<td valign="top">Rebecca looks sort of possessed... Hmm, scary childhood :)<br/>Very pretty pic btw.</td>', 'Rebecca looks sort of possessed... Hmm, scary childhood :)Very pretty pic btw.', '2008-02-05 16:50:42.000000', NULL, 1),
(4460889, 640766, 62787, '<td valign="top">Fantastic artistic representation of a busy street from a child''s POV. Though I sort of wish the actual POV used was a bit lower, to fit a child''s perspective. Though I''m willing to stretch it and accept that the kid was on his dad''s shoulders or something :)<br/>Anyway, this is great, I love it.</td>', 'Fantastic artistic representation of a busy street from a child''s POV. Though I sort of wish the actual POV used was a bit lower, to fit a child''s perspective. Though I''m willing to stretch it and accept that the kid was on his dad''s shoulders or something :)Anyway, this is great, I love it.', '2008-02-05 16:55:08.000000', NULL, 1),
(4460900, 641958, 62787, '<td valign="top">Oh god. Amongst all those staged surgeon shots, this one''s probably the most true to life one, and I''d say also the best. Gives me the creeps, but then, how often do I normally find myself staring out of a womb...<br/>Fantastic shot :)</td>', 'Oh god. Amongst all those staged surgeon shots, this one''s probably the most true to life one, and I''d say also the best. Gives me the creeps, but then, how often do I normally find myself staring out of a womb...Fantastic shot :)', '2008-02-05 16:58:05.000000', NULL, 1),
(4461080, 641368, 70888, '<td valign="top">in focus would have helped,good idea...</td>', 'in focus would have helped,good idea...', '2008-02-05 18:25:14.000000', NULL, 1),
(4461090, 641958, 70888, '<td valign="top">LMFAO! 7 JUST FOR DOIN IT!</td>', 'LMFAO! 7 JUST FOR DOIN IT!', '2008-02-05 18:27:47.000000', NULL, 1),
(4461172, 641630, 53316, '<td valign="top">Beautiful, beautiful photo. Love the colors! Also the contrast and the way it is very abstract while still being recognizable.  Good job.</td>', 'Beautiful, beautiful photo. Love the colors! Also the contrast and the way it is very abstract while still being recognizable.  Good job.', '2008-02-05 19:00:33.000000', NULL, 1),
(4461212, 642121, 53509, '<td valign="top">I think the lighting is effective here, but I don''t think it meets the challenge topic strongly though...</td>', 'I think the lighting is effective here, but I don''t think it meets the challenge topic strongly though...', '2008-02-05 19:22:32.000000', NULL, 1),
(4461217, 641926, 53509, '<td valign="top">Good range of expressions, and I like the expressions. I wish it had a dreamier sort of quality to it.</td>', 'Good range of expressions, and I like the expressions. I wish it had a dreamier sort of quality to it.', '2008-02-05 19:23:15.000000', NULL, 1),
(4461219, 641865, 53509, '<td valign="top">I''m honestly not really sure where you''re going with this one</td>', 'I''m honestly not really sure where you''re going with this one', '2008-02-05 19:24:15.000000', NULL, 1),
(4461221, 641084, 53509, '<td valign="top">I''m not quite sure what you''re trying to do here.</td>', 'I''m not quite sure what you''re trying to do here.', '2008-02-05 19:24:36.000000', NULL, 1),
(4461222, 641162, 53509, '<td valign="top">I remember this game!!!</td>', 'I remember this game!!!', '2008-02-05 19:24:54.000000', NULL, 1),
(4461223, 640618, 53509, '<td valign="top">Too bad the bee isn''t bigger. I like the colours though.</td>', 'Too bad the bee isn''t bigger. I like the colours though.', '2008-02-05 19:25:18.000000', NULL, 1),
(4461326, 642099, 1024, '<td valign="top">This is the most nostalgic of this entire challenge for me.  It brings back such fond memories of the Dick and Jane books (the illustrations are very similar.  10 for the trip down memory lane.</td>', 'This is the most nostalgic of this entire challenge for me.  It brings back such fond memories of the Dick and Jane books (the illustrations are very similar.  10 for the trip down memory lane.', '2008-02-05 20:25:18.000000', NULL, 1),
(4461327, 640277, 1024, '<td valign="top">Wow, I remember the samwe thing, different clock but such a wonderful memory.  Thank you.</td>', 'Wow, I remember the samwe thing, different clock but such a wonderful memory.  Thank you.', '2008-02-05 20:26:03.000000', NULL, 1),
(4461431, 641193, 88136, '<td valign="top">oh damn, that looks really unpleasent.  this is a great way to express your memory. great job</td>', 'oh damn, that looks really unpleasent.  this is a great way to express your memory. great job', '2008-02-05 21:26:00.000000', NULL, 1),
(4461438, 641347, 88136, '<td valign="top">this is really grainy</td>', 'this is really grainy', '2008-02-05 21:26:28.000000', NULL, 1),
(4461441, 641672, 65234, '<td valign="top">You seem to have been riding on the floor of the front seat.  Pre-child safety seats that was certainly possible.</td>', 'You seem to have been riding on the floor of the front seat.  Pre-child safety seats that was certainly possible.', '2008-02-05 21:26:48.000000', NULL, 1),
(4461453, 641492, 88136, '<td valign="top">HAH! thats incredible.  cheers!</td>', 'HAH! thats incredible.  cheers!', '2008-02-05 21:27:37.000000', NULL, 1),
(4461455, 642085, 88136, '<td valign="top">oh! thats gnarly! i like the painted toenails</td>', 'oh! thats gnarly! i like the painted toenails', '2008-02-05 21:28:52.000000', NULL, 1),
(4461460, 641972, 65234, '<td valign="top">And curved in strange ways.  Not sure what I think about the fisheye but I do think this would be really cool if the door was open (scary busdriver optional but fun).</td>', 'And curved in strange ways.  Not sure what I think about the fisheye but I do think this would be really cool if the door was open (scary busdriver optional but fun).', '2008-02-05 21:30:59.000000', NULL, 1),
(4461467, 642078, 65234, '<td valign="top">That looks like one of those toys they can''t sell any more because you could pinch your little fingers in the springs.  Or someone else''s, say a sibling.  Poor old thing needs a paint job.</td>', 'That looks like one of those toys they can''t sell any more because you could pinch your little fingers in the springs.  Or someone else''s, say a sibling.  Poor old thing needs a paint job.', '2008-02-05 21:32:46.000000', NULL, 1),
(4461475, 641193, 65234, '<td valign="top">Um, ewww.  Those are some awfully big spots.</td>', 'Um, ewww.  Those are some awfully big spots.', '2008-02-05 21:35:15.000000', NULL, 1),
(4461480, 641649, 65234, '<td valign="top">AAARRRGGGHHHH!<br/> <br/>OK, I scrolled down so I could stop seeing the eyes.  Very sorry about your nightmare memory!</td>', 'AAARRRGGGHHHH! OK, I scrolled down so I could stop seeing the eyes.  Very sorry about your nightmare memory!', '2008-02-05 21:36:39.000000', NULL, 1),
(4461483, 641497, 65234, '<td valign="top">I feel like it needs some bright plastic toys or a sand castle or something.</td>', 'I feel like it needs some bright plastic toys or a sand castle or something.', '2008-02-05 21:37:43.000000', NULL, 1),
(4461488, 642051, 65234, '<td valign="top">Nice.  Everyone has their own favorite way to eat those, and you did a nice job representing the dunkers.</td>', 'Nice.  Everyone has their own favorite way to eat those, and you did a nice job representing the dunkers.', '2008-02-05 21:38:24.000000', NULL, 1),
(4461495, 641865, 65234, '<td valign="top">Before I read the title I was afraid you were remembering a massacre of some kind!  If I were your mother I''d make you clean all that mess!!</td>', 'Before I read the title I was afraid you were remembering a massacre of some kind!  If I were your mother I''d make you clean all that mess!!', '2008-02-05 21:40:57.000000', NULL, 1),
(4461498, 641950, 65234, '<td valign="top">I wasn''t allowed to have a dog when I was a kid ::sniff::  Had to settle for attaching myself to my grandparents'' dog when we visited once a year.</td>', 'I wasn''t allowed to have a dog when I was a kid ::sniff::  Had to settle for attaching myself to my grandparents'' dog when we visited once a year.', '2008-02-05 21:42:19.000000', NULL, 1),
(4461500, 642114, 65234, '<td valign="top">She has freckles!  Looks to be in good shape; I love how her eyes are lit and they even have catchlights.</td>', 'She has freckles!  Looks to be in good shape; I love how her eyes are lit and they even have catchlights.', '2008-02-05 21:43:17.000000', NULL, 1),
(4461504, 641926, 65234, '<td valign="top">None of them look like they''re going to pinch your cheek, so count your little blessings!  Good perspective from inside the stroller.</td>', 'None of them look like they''re going to pinch your cheek, so count your little blessings!  Good perspective from inside the stroller.', '2008-02-05 21:46:18.000000', NULL, 1),
(4461506, 642006, 65234, '<td valign="top">You loved all the paint off of it.</td>', 'You loved all the paint off of it.', '2008-02-05 21:46:48.000000', NULL, 1),
(4461550, 641198, 65234, '<td valign="top">Good choice of perspective and I like the motion blur.</td>', 'Good choice of perspective and I like the motion blur.', '2008-02-05 22:01:07.000000', NULL, 1),
(4461557, 640377, 65234, '<td valign="top">Aww, it''s Raggedy Ann.  I had Raggedy Andy as a kid.  I gave him to my oldest daughter when she was about 2.  Our dog ate his face shortly thereafter ::sigh::<br/> <br/>You did a better job caring for your memories!</td>', 'Aww, it''s Raggedy Ann.  I had Raggedy Andy as a kid.  I gave him to my oldest daughter when she was about 2.  Our dog ate his face shortly thereafter ::sigh:: You did a better job caring for your memories!', '2008-02-05 22:02:54.000000', NULL, 1),
(4461559, 641902, 65234, '<td valign="top">Lucky you!</td>', 'Lucky you!', '2008-02-05 22:03:24.000000', NULL, 1),
(4461561, 641544, 65234, '<td valign="top">Very pretty scene.  Border is a little heavy for the delicacy of the branches.</td>', 'Very pretty scene.  Border is a little heavy for the delicacy of the branches.', '2008-02-05 22:04:11.000000', NULL, 1),
