(4474898, 641377, 8637, '<td valign="top">Beautiful ships and great lighting.  The ramp distracts though.</td>', 'Beautiful ships and great lighting.  The ramp distracts though.', '2008-02-10 10:02:34.000000', NULL, 1),
(4474900, 641900, 83080, '<td valign="top">Great interpretation.  The shadows are a bit strong for me and the DOF on the shallow side.  My first reaction to the composition was to wish that you had included more of the person holding the spoon.  After a few moments I warmed up to the subtle impled connection (we all know what''s going on off frame) and the strength of the child''s POV.  Nice placement of the spoon.</td>', 'Great interpretation.  The shadows are a bit strong for me and the DOF on the shallow side.  My first reaction to the composition was to wish that you had included more of the person holding the spoon.  After a few moments I warmed up to the subtle impled connection (we all know what''s going on off frame) and the strength of the child''s POV.  Nice placement of the spoon.', '2008-02-10 10:02:42.000000', NULL, 1),
(4474907, 641347, 8637, '<td valign="top">Agree with the title...but "goes" should be "go".  Image appears foggy...not sure what happened to the colors.</td>', 'Agree with the title...but "goes" should be "go".  Image appears foggy...not sure what happened to the colors.', '2008-02-10 10:04:25.000000', NULL, 1),
