(4475372, 641577, 46314, '<td valign="top">Nice composition - nice detail.</td>', 'Nice composition - nice detail.', '2008-02-10 14:50:27.000000', NULL, 1),
(4475375, 641342, 46314, '<td valign="top">The slightly desaturated colour is nice, but the patterns on the carpet are very distracting, and detract from the focal point of the image.</td>', 'The slightly desaturated colour is nice, but the patterns on the carpet are very distracting, and detract from the focal point of the image.', '2008-02-10 14:51:28.000000', NULL, 1),
(4475376, 641544, 46314, '<td valign="top">Nice detail and tone.</td>', 'Nice detail and tone.', '2008-02-10 14:51:52.000000', NULL, 1),
