(4475394, 641619, 55838, '<td valign="top">Beautiful protrait!!  Great lights and focus and a lovely model. Back to bump you up to 9.</td>', 'Beautiful protrait!!  Great lights and focus and a lovely model. Back to bump you up to 9.', '2008-02-10 15:02:17.000000', NULL, 1),
(4475397, 642000, 55838, '<td valign="top">Lovely warm shot and the dirty fingernails are great - afterall, are they ever clean for long?!  Nice light and contrast.  Back to bump you up to 8.</td>', 'Lovely warm shot and the dirty fingernails are great - afterall, are they ever clean for long?!  Nice light and contrast.  Back to bump you up to 8.', '2008-02-10 15:03:51.000000', NULL, 1),
(4475398, 641972, 55838, '<td valign="top">Great perspective and a wonderful idea.  One of my first real memories too.  Well done.  Back to bump you up to 8.</td>', 'Great perspective and a wonderful idea.  One of my first real memories too.  Well done.  Back to bump you up to 8.', '2008-02-10 15:04:42.000000', NULL, 1),
(4475408, 641972, 46314, '<td valign="top">I like the use of the extreme wide angle to emphasise the scary, monster-like quality of the bus. Nice colour and details. My yellow ribbon choice.</td>', 'I like the use of the extreme wide angle to emphasise the scary, monster-like quality of the bus. Nice colour and details. My yellow ribbon choice.', '2008-02-10 15:07:42.000000', NULL, 1),
(4475409, 642085, 46314, '<td valign="top">Well executed. I like the use of DOF, and nice balance in the composition.<br/>After going through all the other images that used this same idea, this one was by far the best of them. Well done. My red ribbon choice.</td>', 'Well executed. I like the use of DOF, and nice balance in the composition.After going through all the other images that used this same idea, this one was by far the best of them. Well done. My red ribbon choice.', '2008-02-10 15:07:45.000000', NULL, 1),
(4475410, 642124, 46314, '<td valign="top">Clever idea. A lot of humour in the execution. Good job. Because of how well it met the challenge, I''m making this my blue-ribbon choice.</td>', 'Clever idea. A lot of humour in the execution. Good job. Because of how well it met the challenge, I''m making this my blue-ribbon choice.', '2008-02-10 15:08:27.000000', NULL, 1),
