(4476152, 641630, 50695, '<td valign="top">I''m giving you a Posthumous Yellow Ribbon for trying to create what an ancient memory might look like. <br/> <br/><img alt="'' . substr(''//blackyak.com/dpc/yellowpost.jpg'', strrpos(''//blackyak.com/dpc/yellowpost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/yellowpost.jpg"/></td>', 'I''m giving you a Posthumous Yellow Ribbon for trying to create what an ancient memory might look like.  ', '2008-02-10 22:25:17.000000', NULL, 1),
(4476155, 641869, 48697, '<td valign="top">the sky seems a bit bright and overpowers the image of the old building, looks lke a pretty cool place though.</td>', 'the sky seems a bit bright and overpowers the image of the old building, looks lke a pretty cool place though.', '2008-02-10 22:25:25.000000', NULL, 1),
