(4476573, 641630, 33352, '<td valign="top">Well thought out Julie, I like the color used to to depict the nightmare, good to see <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=50695" rel="nofollow" target="_blank">posthumous</a> giving this a yellow for your subjectivity.</td>', 'Well thought out Julie, I like the color used to to depict the nightmare, good to see  posthumous giving this a yellow for your subjectivity.', '2008-02-11 01:06:23.000000', NULL, 0),
(4476582, 642124, 60862, '<td valign="top">Ha!  Well done. :)</td>', 'Ha!  Well done. :)', '2008-02-11 01:07:56.000000', NULL, 0),
(4476589, 642111, 60862, '<td valign="top">Sweet shot, Mark.  We''ve been taking our kids camping since my oldest was literally 15 months old.  You did a great job using the leading lines of the trunks to drive the eye to the boy, and the contrasting colors are terrific!</td>', 'Sweet shot, Mark.  We''ve been taking our kids camping since my oldest was literally 15 months old.  You did a great job using the leading lines of the trunks to drive the eye to the boy, and the contrasting colors are terrific!', '2008-02-11 01:08:52.000000', NULL, 0),
